<?php
require 'header.php';
master_admin_required();
$db = db_load();
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $editId = trim(post('edit_id'));
    $profileType = post($editId !== '' ? 'edit_profile_type' : 'profile_type') === 'doctor' ? 'doctor' : 'subadmin';
    $value = static fn(string $key, $default = '') => post($editId !== '' ? 'edit_' . $key : $key, $default);
    $username = trim($value('username'));
    $password = $value('password');
    if ($profileType === 'subadmin' && ($username === '' || $password === '')) {
        redirect('manage-users.php');
    }
    if ($profileType === 'doctor' || ($username !== '' && $password !== '')) {
        if (!isset($db['admins']) || !is_array($db['admins'])) $db['admins'] = [];
        $permissions = [
            'view' => !empty($_POST[$editId !== '' ? 'edit_perm_view' : 'perm_view']),
            'edit' => !empty($_POST[$editId !== '' ? 'edit_perm_edit' : 'perm_edit']),
            'delete' => !empty($_POST[$editId !== '' ? 'edit_perm_delete' : 'perm_delete'])
        ];
        $record = ['username' => $profileType === 'subadmin' ? $username : '', 'password' => $profileType === 'subadmin' ? password_hash($password, PASSWORD_DEFAULT) : '', 'role' => $profileType, 'profile_type' => $profileType, 'name' => trim($value('name')), 'gender' => $value('gender'), 'photo' => upload_image('photo'), 'dob' => $value('dob'), 'designation' => trim($value('designation')), 'mobile' => trim($value('mobile')), 'degree' => trim($value('degree')), 'email' => trim($value('email')), 'address' => trim($value('address')), 'is_doctor' => $profileType === 'doctor' || !empty($_POST[$editId !== '' ? 'edit_is_doctor' : 'is_doctor']), 'show_on_home' => !empty($_POST[$editId !== '' ? 'edit_show_on_home' : 'show_on_home']), 'permissions' => $profileType === 'subadmin' ? $permissions : ['view' => false, 'edit' => false, 'delete' => false]];
        if ($editId !== '') {
            foreach ($db['admins'] as &$admin) {
                if ((string)($admin['id'] ?? '') !== $editId) continue;
                if ($profileType === 'subadmin' && $password === '') $record['password'] = $admin['password'] ?? '';
                if ($record['photo'] === '') $record['photo'] = $admin['photo'] ?? '';
                foreach (['gender', 'dob', 'email', 'address'] as $preservedField) {
                    if (!array_key_exists('edit_' . $preservedField, $_POST)) $record[$preservedField] = $admin[$preservedField] ?? '';
                }
                $record['id'] = $admin['id'];
                $record['created_at'] = $admin['created_at'] ?? now_iso();
                $record['updated_at'] = now_iso();
                $admin = array_merge($admin, $record);
                break;
            }
            unset($admin);
        } else {
            $record['id'] = make_id();
            $record['created_at'] = now_iso();
            $db['admins'][] = $record;
        }
        db_save($db);
    }
    redirect('manage-users.php');
}
?>
