<script>(function(){const form=document.querySelector('#userModal form');if(!form)return;const grid=form.querySelector('.form-grid');const typeField=document.createElement('div');typeField.className='field full profile-type-field';typeField.innerHTML='<label>Profile Type</label><div class="gender-options"><label><input type="radio" name="profile_type" value="subadmin" checked> Sub Admin</label><label><input type="radio" name="profile_type" value="doctor"> Doctor Profile</label></div>';grid.prepend(typeField);const username=form.querySelector('[name="username"]');const password=form.querySelector('[name="password"]');const doctor=form.querySelector('[name="is_doctor"]');form.querySelectorAll('[name="profile_type"]').forEach(function(radio){radio.addEventListener('change',function(){const isDoctor=this.value==='doctor';username.required=!isDoctor;password.required=!isDoctor;username.disabled=isDoctor;password.disabled=isDoctor;if(isDoctor){username.value='';password.value='';if(doctor)doctor.checked=true;}});});})();</script>
<script>(function(){const modal=document.getElementById('userModal');const close=()=>{modal.classList.remove('show');modal.setAttribute('aria-hidden','true');document.body.style.overflow='';};document.getElementById('openUserModal').addEventListener('click',()=>{modal.classList.add('show');modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';});document.getElementById('closeUserModal').addEventListener('click',close);modal.addEventListener('click',e=>{if(e.target===modal)close();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.classList.contains('show'))close();});document.querySelectorAll('.password-toggle-btn').forEach(function(button){button.addEventListener('click',function(){const input=document.getElementById(this.dataset.target);if(!input)return;const isPassword=input.type==='password';input.type=isPassword?'text':'password';this.textContent=isPassword?'🙈':'👁';this.setAttribute('aria-label',isPassword?'Hide password':'Show password');});});})();</script>
<script>
(function(){
    const modal=document.getElementById('editUserModal');
    const form=modal.querySelector('form');
    const profiles=<?= json_encode(array_values(array_map(function($admin){ return ['id'=>(string)($admin['id']??''),'profile_type'=>$admin['profile_type']??$admin['role']??'subadmin','username'=>$admin['username']??'','name'=>$admin['name']??'','designation'=>$admin['designation']??'','mobile'=>$admin['mobile']??'','degree'=>$admin['degree']??'','is_doctor'=>!empty($admin['is_doctor']),'show_on_home'=>!empty($admin['show_on_home']),'permissions'=>admin_permissions_for($admin)]; }, $db['admins']??[])), JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP) ?>;
    const select=document.createElement('select');select.name='profile_picker';select.className='profile-picker';select.innerHTML='<option value="">Select profile to edit</option>'+profiles.map(function(profile){return '<option value="'+profile.id+'">'+(profile.name||profile.username||'Profile')+'</option>';}).join('');
    const pickerField=document.createElement('div');pickerField.className='field full';pickerField.innerHTML='<label>Select Profile</label>';pickerField.appendChild(select);form.querySelector('.form-grid').prepend(pickerField);
    const close=function(){modal.classList.remove('show');modal.setAttribute('aria-hidden','true');};
    function syncType(){const doctor=form.querySelector('[name="edit_profile_type"]:checked').value==='doctor';form.querySelector('[name="edit_username"]').disabled=doctor;form.querySelector('[name="edit_username"]').required=!doctor;form.querySelector('[name="edit_password"]').disabled=doctor;form.querySelector('[name="edit_is_doctor"]').checked=doctor||form.querySelector('[name="edit_is_doctor"]').checked;}
    select.addEventListener('change',function(){const profile=profiles.find(function(item){return item.id===select.value;});if(!profile)return;form.querySelector('[name="edit_id"]').value=profile.id;form.querySelector('[name="edit_username"]').value=profile.username;form.querySelector('[name="edit_name"]').value=profile.name;form.querySelector('[name="edit_designation"]').value=profile.designation;form.querySelector('[name="edit_mobile"]').value=profile.mobile;form.querySelector('[name="edit_degree"]').value=profile.degree;form.querySelectorAll('[name="edit_profile_type"]').forEach(function(radio){radio.checked=radio.value===profile.profile_type;});form.querySelector('[name="edit_is_doctor"]').checked=profile.is_doctor;form.querySelector('[name="edit_show_on_home"]').checked=profile.show_on_home;form.querySelector('[name="edit_perm_view"]').checked=profile.permissions.view;form.querySelector('[name="edit_perm_edit"]').checked=profile.permissions.edit;form.querySelector('[name="edit_perm_delete"]').checked=profile.permissions.delete;syncType();});
    form.querySelectorAll('[name="edit_profile_type"]').forEach(function(radio){radio.addEventListener('change',syncType);});
    function openEditor(id){select.value=id;select.dispatchEvent(new Event('change'));modal.classList.add('show');modal.setAttribute('aria-hidden','false');}
    document.getElementById('openEditUserModal').addEventListener('click',function(){modal.classList.add('show');modal.setAttribute('aria-hidden','false');});document.querySelectorAll('a[href^="admin-user-edit.php?id="]').forEach(function(link){link.addEventListener('click',function(event){event.preventDefault();openEditor(new URL(link.href).searchParams.get('id'));});});document.getElementById('closeEditUserModal').addEventListener('click',close);modal.addEventListener('click',function(event){if(event.target===modal)close();});
})();
</script>
